const STY = (acc) => `position:absolute;left:70px;width:800px;height:210px;display:flex;flex-direction:column;align-items:center;justify-content:center;border-radius:46px;box-shadow:0 26px 40px -14px rgba(0,0,0,.5),inset 0 4px 0 rgba(255,255,255,.5);background:linear-gradient(180deg,color-mix(in srgb,${acc} 72%,#fff),${acc} 55%,color-mix(in srgb,${acc} 84%,#000));color:#0b1020;font-family:inherit;font-weight:800;opacity:0;`;

root.innerHTML = `
  <div id="h" style="position:absolute;top:50px;width:100%;text-align:center;color:#ffffff;font-size:46px;opacity:0;text-transform:uppercase;letter-spacing:1px;">shanselman / gputaskman</div>
  <div id="stars" style="position:absolute;top:115px;width:100%;text-align:center;color:#ffffff;font-size:44px;opacity:0;">3,700 GITHUB STARS</div>

  <div id="c0" style="${STY('var(--acc)')}top:200px;">
    <div style="font-size:40px;opacity:0.8;margin-bottom:5px;">PER-PROCESS VRAM</div>
    <div id="v0" style="font-size:85px;line-height:1;">0.0 GB</div>
  </div>

  <div id="c1" style="${STY('var(--acc2)')}top:440px;">
    <div style="font-size:40px;opacity:0.8;margin-bottom:5px;">KV-CACHE COSTS</div>
    <div id="v1" style="font-size:85px;line-height:1;">0.00 GB</div>
  </div>

  <div id="c2" style="${STY('var(--acc)')}top:680px;">
    <div style="font-size:40px;opacity:0.8;margin-bottom:5px;">OLLAMA THROUGHPUT</div>
    <div id="v2" style="font-size:85px;line-height:1;">0 TK/S</div>
  </div>
`;

const h = root.querySelector('#h');
const stars = root.querySelector('#stars');
const cards = [0, 1, 2].map(i => root.querySelector(`#c${i}`));
const v0 = root.querySelector('#v0');
const v1 = root.querySelector('#v1');
const v2 = root.querySelector('#v2');

function frame(t, p, d) {
  const animT = Math.min(t, d * 0.55);

  const hS = spr(animT, 0, 0.8, 5);
  h.style.opacity = hS;
  h.style.transform = `translateY(${lerp(20, 0, hS)}px)`;

  const stS = spr(animT, 0.1, 0.8, 5);
  stars.style.opacity = stS;
  stars.style.transform = `scale(${lerp(0.9, 1, stS)})`;

  cards.forEach((card, i) => {
    const cs = spr(animT, 0.2 + i * 0.1, 0.8, 5);
    card.style.opacity = cs;
    card.style.transform = `translateY(${lerp(50, 0, cs)}px)`;
  });

  const dataS = spr(animT, 0.5, 0.9, 3);

  // Per-Process VRAM (Ollama Example)
  const vram = lerp(0, 8.4, dataS);
  v0.textContent = `${vram.toFixed(1)} GB`;

  // KV Cache Growth
  const kv = lerp(0, 1.18, dataS);
  v1.textContent = `${kv.toFixed(2)} GB`;

  // Live Throughput
  const tput = Math.floor(lerp(0, 48, dataS));
  v2.textContent = `${tput} TK/S`;
}
